/**
 * Single source of truth for the docs site and the registry generator.
 * Plain data, no imports — `scripts/build-registry.ts` reads this file directly.
 */

export type CatalogGroup = "ui" | "dx" | "agents" | "charts" | "motion" | "text" | "transitions" | "effects" | "elements";

export type CatalogItem = {
  slug: string;
  title: string;
  description: string;
  group: CatalogGroup;
  /** Base UI component this wraps (for the "Primitive" link). */
  base?: string;
  /** Third-party library it wraps, shown as a link. */
  lib?: { name: string; href: string };
  isNew?: boolean;
  /** Source path under `components/` for multi-file items, e.g. "motion/swap". */
  src?: string;
};

const ui = (slug: string, title: string, description: string, extra: Partial<CatalogItem> = {}): CatalogItem => ({
  slug,
  title,
  description,
  group: "ui",
  ...extra,
});
const dx = (slug: string, title: string, description: string, extra: Partial<CatalogItem> = {}): CatalogItem => ({
  slug,
  title,
  description,
  group: "dx",
  isNew: true,
  ...extra,
});

const kit =
  (group: Exclude<CatalogGroup, "ui" | "dx">) =>
  (slug: string, src: string, title: string, description: string): CatalogItem => ({
    slug,
    title,
    description,
    group,
    src,
    isNew: true,
  });
const ag = kit("agents");
const ch = kit("charts");
const mo = kit("motion");
const te = kit("text");
const tr = kit("transitions");
const ef = kit("effects");
const el = kit("elements");

